int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("session required");auto graph=loadGraph(argv[1]);RetainedShotTimelineCandidate timeline(graph,2237),scalarTimeline(graph,2237);std::map<std::string,std::vector<GeometryBoneCandidate>>cache;std::filesystem::path content=R"(D:\SteamLibrary\steamapps\common\SourceFilmmaker\game\usermod)";auto loader=[&](const std::string&asset)->const std::vector<GeometryBoneCandidate>&{auto found=cache.find(asset);if(found!=cache.end())return found->second;std::filesystem::path relative(asset);if(relative.is_absolute()||relative.has_root_name())throw std::runtime_error("asset path");for(auto&part:relative)if(part=="..")throw std::runtime_error("asset traversal");std::ifstream file(content/relative,std::ios::binary);if(!file)throw std::runtime_error("MDL missing");std::vector<uint8_t>bytes((std::istreambuf_iterator<char>(file)),{});return cache.emplace(asset,readGeometrySkeletonCandidate(bytes)).first->second;};size_t frames=0,instances=0;for(int32_t tick:{1259500,1259667,1259833,1259500,1392000,1392167,1392333,1392000}){auto step=evaluateLiveSessionSceneCandidate(timeline,tick,512,512);auto poses=readSessionScenePosesCandidate(timeline.graph(),step.scene,loader,true,true);auto scalarStep=evaluateLiveSessionSceneCandidate(scalarTimeline,tick,512,512,0,0);auto scalarPoses=readSessionScenePosesCandidate(scalarTimeline.graph(),scalarStep.scene,loader,true,true);if(poses.shot!=scalarPoses.shot||poses.models.size()!=scalarPoses.models.size()||std::memcmp(poses.camera.rows.data(),scalarPoses.camera.rows.data(),64))throw std::runtime_error("parallel scene camera or identity mismatch");for(size_t n=0;n<poses.models.size();++n){auto&a=poses.models[n];auto&b=scalarPoses.models[n];if(a.model.id!=b.model.id||a.model.skin!=b.model.skin||a.model.body!=b.model.body||a.model.visible!=b.model.visible||a.model.placement.asset!=b.model.placement.asset||std::memcmp(a.model.placement.matrix.rows.data(),b.model.placement.matrix.rows.data(),64)||a.locals.size()!=b.locals.size())throw std::runtime_error("parallel scene model mismatch");for(size_t bone=0;bone<a.locals.size();++bone)if(std::memcmp(a.locals[bone].data(),b.locals[bone].data(),48))throw std::runtime_error("parallel scene bone pose mismatch");}if(poses.models.size()!=step.scene.models.size())throw std::runtime_error("pose extraction lost models");size_t total=0,procedures=0;for(auto&entry:poses.models){total+=entry.locals.size();for(auto&bone:loader(entry.model.placement.asset))procedures+=bone.procedure!=0;}std::cout<<"tick="<<tick<<" models="<<poses.models.size()<<" local_matrices="<<total<<" procedural_pending="<<procedures<<"\n";++frames;instances+=poses.models.size();}if(frames!=8||instances!=28||cache.size()!=7)throw std::runtime_error("coverage");std::cout<<"evaluated scene poses parallel_scalar_byte_exact=1 backward_seek_checked=1 passed frames="<<frames<<" model_instances="<<instances<<" skeleton_loads="<<cache.size()<<" scale_and_mapping=experimental procedural_evaluation=unfinished gpu_multi_model=unfinished\n";return 0;}catch(std::exception&e){std::cerr<<e.what();return 1;}}
